// The Lamina PDF docs site (todo B7a): Starlight, with the @laminapdf/sdk API reference generated by
// TypeDoc at build time and every internal link checked (starlight-links-validator, plus
// plugins/integrations.mjs for what it can't see). Code on the pages is read from the tested
// example files (src/components/Snippet.astro), the code table from fixtures/codes.json, and the
// code pages from docs/errors/ (src/pages/reference/codes/[code].astro, plugins/error-pages.mjs).
// @laminapdf/site-kit fills the CSP's inline-script hashes into dist/_headers, as for the website.
//
// Build-time settings (environment variables):
// - LAMINA_PDF_DOCS_TYPEDOC=0 leaves the TypeDoc reference out (the package's `typecheck` uses it,
//   so the TypeScript checks generate the reference only once, in the build).
// - LAMINA_PDF_ENV=production builds the released docs, docs.laminapdf.com: the header names the
//   version. Every other build (next.docs.laminapdf.com, the previews, a local build) says on every
//   page that it describes unreleased changes, and is noindex (plugins/release.mjs). Every build
//   lets crawlers in (robots.txt), so they read that noindex; only the released docs name a sitemap.
import { fileURLToPath } from "node:url";
import starlight from "@astrojs/starlight";
import { inlineStylesToClasses } from "@laminapdf/site-kit/inline-styles";
import { inlineScriptHashes, pageFiles, previewNoindex } from "@laminapdf/site-kit/integrations";
import { robots } from "@laminapdf/site-kit/robots";
import { defineConfig } from "astro/config";
import starlightLinksValidator from "starlight-links-validator";
import starlightTypeDoc, { typeDocSidebarGroup } from "starlight-typedoc";
import { agentDocs, packageVersion } from "./plugins/agent-docs.mjs";
import { cliDownloadChecks } from "./plugins/cli-downloads.mjs";
import { guidePdfAvailable, guidePdfStep, onePageViews } from "./plugins/guide.mjs";
import {
  checkedLinks,
  codePages,
  examplePdfs,
  repositoryLinks,
  WEBSITE_ICONS,
  websiteIcons,
} from "./plugins/integrations.mjs";
import { releaseChecks, versionInPages } from "./plugins/release.mjs";
import { EDIT_BASE, REPOSITORY } from "./plugins/repository.mjs";
import { sidebar, sidebarRoutes } from "./plugins/sidebar.mjs";
import { sourceRevision, TYPEDOC_OUTPUT } from "./plugins/typedoc-sources.mjs";

const ROOT = new URL("../../", import.meta.url);
/** Production's address, which every error's `docsUrl` starts with (fixtures/codes.json). */
const SITE = "https://docs.laminapdf.com";
/** The website's pages: the shared header links to one only once it exists (W1d). */
const WEBSITE_PAGES = pageFiles(new URL("apps/site/src/pages/", ROOT));
const TYPEDOC = process.env.LAMINA_PDF_DOCS_TYPEDOC !== "0";
/** The version the docs describe, and whether they are the released docs. */
const DOCS_RELEASE = { version: await packageVersion(), release: process.env.LAMINA_PDF_ENV === "production" };

const typeDoc = starlightTypeDoc({
  // TypeDoc reads entry points as globs, which take only forward slashes (not Windows' `\`).
  entryPoints: [fileURLToPath(new URL("packages/sdk/src/index.ts", ROOT)).replaceAll("\\", "/")],
  tsconfig: fileURLToPath(new URL("packages/sdk/tsconfig.build.json", ROOT)),
  output: TYPEDOC_OUTPUT,
  sidebar: { label: "@laminapdf/sdk (TypeDoc)", collapsed: true },
  typeDoc: {
    // The wasm-bindgen types come from @laminapdf/wasm's dist/, which only `cargo xtask wasm`
    // builds: without it the records are named but not expanded, and the build goes on.
    skipErrorChecking: true,
    excludeInternal: true,
    excludePrivate: true,
    // "Defined in" links to the file at the release's tag (main for unreleased docs). disableGit
    // builds them from the template alone, so a worktree or a shallow CI checkout links the same way.
    disableGit: true,
    // Declarations as code blocks, one member or union case to a line, rather than a paragraph
    // of inline code that a long union or object type turns into an unbroken wall of text.
    useCodeBlocks: true,
    displayBasePath: fileURLToPath(ROOT),
    // Sources in node_modules (TypeScript's own types) keep no link: they aren't on GitHub.
    plugin: [fileURLToPath(new URL("plugins/typedoc-sources.mjs", import.meta.url))],
    sourceLinkTemplate: `${REPOSITORY}/blob/${sourceRevision(DOCS_RELEASE)}/{path}#L{line}`,
  },
});

// A default export because that is how Astro reads its configuration.
// Whether this build can make the guide PDF (plugins/guide.mjs): read once, so the pages link it
// exactly when the build writes it.
// `astro dev` never runs the build steps, so only a build writes the PDF.
const GUIDE_PDF = process.argv.includes("build") && guidePdfAvailable();

export default defineConfig({
  // Production's address: canonical links and the sitemap use it (previews too; they're noindex).
  site: SITE,
  // Telemetry is off in the package scripts (ASTRO_TELEMETRY_DISABLED).
  devToolbar: { enabled: false },
  // Style sheets as files, never inline <style>: the CSP's style-src is 'self' (public/_headers).
  build: { inlineStylesheets: "never" },
  vite: {
    define: {
      __SITE_PAGES__: JSON.stringify(WEBSITE_PAGES),
      __DOCS_RELEASE__: JSON.stringify(DOCS_RELEASE),
      __GUIDE_PDF__: JSON.stringify(GUIDE_PDF),
    },
    // Pages write `{{version}}` where they name the version; this fills it in.
    plugins: [versionInPages(DOCS_RELEASE.version)],
  },
  // Moved pages keep their old URLs (static redirects; Workers static assets ignore _redirects).
  redirects: {
    "/guides/errors-and-warnings/": "/concepts/errors-and-warnings/",
    "/guides/open-edit-and-save/": "/guides/edit-a-pdf/",
    "/guides/encrypted-files/": "/guides/password-protected-files/",
    "/guides/limits/": "/guides/untrusted-files/",
    "/guides/off-the-main-thread/": "/guides/keep-the-page-responsive/",
    "/examples/": "/recipes/",
  },
  integrations: [
    starlight({
      title: "Lamina PDF",
      description:
        "Create, read, edit and save PDFs from Rust and TypeScript: one Rust core, as WebAssembly in browsers, Node, Deno, Bun and Cloudflare Workers.",
      social: [{ icon: "github", label: "GitHub", href: REPOSITORY }],
      // "Edit page" opens the page's file on GitHub; generated pages have none (src/routeData.ts).
      editLink: { baseUrl: `${EDIT_BASE}apps/docs/` },
      routeMiddleware: "./src/routeData.ts",
      lastUpdated: false,
      // The website's icon, from its files (plugins/integrations.mjs, `websiteIcons` below).
      favicon: WEBSITE_ICONS.favicon,
      head: WEBSITE_ICONS.head,
      // One header for both sites (@laminapdf/site-kit), with Starlight's search and theme switch;
      // on phones, where the header hides the site's links, the menu lists them. The banner says
      // when the docs describe unreleased changes. Each page links its Markdown twin from its head
      // and offers to copy it under its title.
      components: {
        Banner: "./src/components/Banner.astro",
        Head: "./src/components/Head.astro",
        Header: "./src/components/Header.astro",
        Hero: "./src/components/Hero.astro",
        MobileMenuFooter: "./src/components/MobileMenuFooter.astro",
        PageTitle: "./src/components/PageTitle.astro",
        ThemeSelect: "./src/components/ThemeSelect.astro",
      },
      // The Paper design language (docs/design/paper/design-language.md): its tokens, its fonts,
      // then Starlight's colours and fonts mapped onto them.
      customCss: [
        "@laminapdf/tokens/tokens.css",
        "@laminapdf/fonts/fonts.css",
        "./src/styles/paper.css",
        "./src/styles/diagrams.css",
      ],
      plugins: [
        starlightLinksValidator({
          errorOnLocalLinks: true,
          // Not pages: plugins/integrations.mjs `checkedLinks` checks these (and the code pages).
          exclude: ["/examples/pdf/*", "/reference/codes/*/", "/one-page/*/"],
        }),
        ...(TYPEDOC ? [typeDoc] : []),
      ],
      // The docs as a story (quality plan §3): the order is a decision, so every page is listed.
      sidebar: sidebar(TYPEDOC ? typeDocSidebarGroup : undefined),
    }),
    examplePdfs(new URL("fixtures/golden/examples/", ROOT)),
    codePages(new URL("fixtures/codes.json", ROOT), SITE),
    repositoryLinks("/install/", REPOSITORY, `${EDIT_BASE}apps/docs/src/content/docs/install.mdx`),
    cliDownloadChecks(ROOT),
    websiteIcons(new URL("apps/site/public/", ROOT)),
    // Expressive Code's and Starlight's style attributes become classes in one style sheet, so the
    // CSP needs no 'unsafe-inline'. Starlight's search shows its shortcut by removing the
    // kbd's display: none from its inline script; the class paper.css hides while search loads
    // stands in for it.
    inlineStylesToClasses({
      scripted: [{ tag: "kbd", style: "display: none;", className: "lamina-search-shortcut" }],
    }),
    inlineScriptHashes,
    previewNoindex(process.env.LAMINA_PDF_ENV),
    // Starlight writes sitemap-index.xml from `site`; only the released docs name it.
    robots({ env: process.env.LAMINA_PDF_ENV, sitemap: "https://docs.laminapdf.com/sitemap-index.xml" }),
    agentDocs(sidebarRoutes, { guidePdf: GUIDE_PDF }),
    // The one-page views' ids and heading levels, after agentDocs, which reads the built pages.
    onePageViews,
    // After agentDocs: the guide PDF is built from the twins it writes.
    guidePdfStep({ available: GUIDE_PDF, site: SITE }),
    // After the guide PDF, which pages link to.
    checkedLinks,
    // Last, so it also reads the Markdown twins agentDocs writes.
    releaseChecks(DOCS_RELEASE),
  ],
});
